// Port of lib/battle-cats-rolls/talent.rb.
//
// Ruby's `prepend`/`super()` per-instance decoration (for talents that
// boost a numeric stat like health/damage/speed/cost/cooldowns) has no JS
// equivalent, so those are ported as an explicit ordered-transform pipeline
// registered on the Stat instance (see stat.js's `addAugmenter`) — applying
// transforms in the same order talents are processed reproduces Ruby's
// nested-`super` composition (see stat.js for the proof).
//
// Ruby's dynamic `const_get(constant_name(key))` dispatch (including the
// per-type constants generated by `Ability::Specialization::List.each` /
// `Ability::Immunity::List.each` / `Resistance.set_constants`) is replaced
// by explicit lookup in `build()` below.

import * as Ability from "./ability.js";
import { strong, percent, RANGE_MULTIPLIER } from "./abilityUtility.js";

function valuesRange(values, { suffix = "", show = (x) => x } = {}) {
  const result = [...new Set(values)];
  const firstValue = `${show(result[0])}${suffix}`;
  if (result.length > 1) {
    const lastValue = `${show(result[result.length - 1])}${suffix}`;
    return `${firstValue} ~ ${strong(lastValue)}`;
  }
  return strong(firstValue);
}

// The "first" struct field of the abilities `augmentAbility` ever merges
// into (always `chance`, except Strengthen's `threshold`) — see
// talent.rb:19-29's `ability.first`.
function firstField(ability) {
  return ability.chance !== undefined ? ability.chance : ability.threshold;
}

export class Talent {
  constructor(key, data, ability) {
    this.key = key;
    this.data = data;
    this.ability = ability;
  }

  get name() {
    return this.ability.name;
  }

  get qualifiedName() {
    return this.ability.qualifiedName;
  }

  get qualifiedValueName() {
    return this.ability.qualifiedValueName;
  }

  display(ctx) {
    return this.ability.display(ctx);
  }

  get level() {
    return this.data.max_level;
  }

  get ultra() {
    return !!this.data.ultra;
  }

  min(n = 0) {
    return this.data.minmax[n][0];
  }

  max(n = 0) {
    return this.data.minmax[n][1];
  }

  // Port of Talent#augment (base case: register the numeric-stat augmenter,
  // if any, then just record which attributes this talent touched).
  augment(stat) {
    this.registerAugmenter(stat);
    for (const attribute of this.augmentAttributes()) {
      stat.augmentAttribute(this, attribute);
    }
  }

  registerAugmenter(_stat) {
    // no-op by default; overridden by talents that boost a Stat number.
  }

  augmentAttributes() {
    return [];
  }

  displayFullOrImprove(ctx) {
    return this.data.minmax.length > 1
      ? this.displayFull(ctx)
      : this.displayImprove(ctx);
  }

  augmentAbility(stat, attribute) {
    const target = stat.abilities.find((a) => a instanceof this.ability.constructor);
    if (target) {
      const delta = firstField(this.ability);
      target[attribute] = target[attribute] + delta;
      stat.augmentAttribute(this, this.ability.qualifiedValueName);
    } else {
      stat.abilities.push(this.ability);
      stat.augmentAttribute(this, this.ability.qualifiedName);
    }
  }
}

export class IncreaseHealth extends Talent {
  get name() {
    return "Increase";
  }
  display() {
    return `${strong("Health")} by ${this.min()}% ~ ${percent(this.max())} by ${this.level} levels`;
  }
  registerAugmenter(stat) {
    const talent = this;
    stat.addAugmenter("healthRaw", (v) => v * (1 + talent.max() / 100));
  }
  augmentAttributes() {
    return ["health"];
  }
}

export class IncreaseDamage extends Talent {
  get name() {
    return "Increase";
  }
  display() {
    return `${strong("Damage")} by ${this.min()}% ~ ${percent(this.max())} by ${this.level} levels`;
  }
  registerAugmenter(stat) {
    const talent = this;
    stat.addAugmenter("damageRaw", (v) => (v != null ? v * (1 + talent.max() / 100) : v));
  }
  augmentAttributes() {
    return ["damage", "damage_sum", "dps", "dps_sum"];
  }
}

export class IncreaseSpeed extends Talent {
  get name() {
    return "Increase";
  }
  display(ctx) {
    const from = ctx.view.statSpeed(this.min());
    const to = ctx.view.statSpeed(this.max());
    return `${strong("Speed")} by ${from} ~ ${strong(to)} by ${this.level} levels`;
  }
  registerAugmenter(stat) {
    const talent = this;
    stat.addAugmenter("speed", (v) => v + talent.max());
  }
  augmentAttributes() {
    return ["speed"];
  }
}

const CHAPTER2_COST_MULTIPLIER = 1.5;

export class ReduceCost extends Talent {
  get name() {
    return "Reduce";
  }
  display() {
    return `${strong("Cost")} by ${this.min()} ~ ${strong(this.max())} by ${this.level} levels`;
  }
  min(n = 0) {
    return Math.round(super.min(n) * CHAPTER2_COST_MULTIPLIER);
  }
  max(n = 0) {
    return Math.round(super.max(n) * CHAPTER2_COST_MULTIPLIER);
  }
  registerAugmenter(stat) {
    const talent = this;
    stat.addAugmenter("productionCost", (v) =>
      typeof v === "number" ? v - talent.max() : v
    );
  }
  augmentAttributes() {
    return ["production_cost"];
  }
}

export class ReduceProductionCooldown extends Talent {
  get name() {
    return "Reduce";
  }
  display(ctx) {
    const values = valuesRange(this.data.minmax[0], { show: (v) => ctx.view.statTime(v) });
    return `${strong("Production cooldown")} by ${values} by ${this.level} levels`;
  }
  registerAugmenter(stat) {
    const talent = this;
    stat.addAugmenter("productionCooldown", (v) =>
      typeof v === "number" ? v - talent.max() : v
    );
  }
  augmentAttributes() {
    return ["production_cooldown"];
  }
}

export class ReduceAttackCooldown extends Talent {
  get name() {
    return "Reduce";
  }
  display() {
    const values = valuesRange(this.data.minmax[0], { suffix: "%" });
    return `${strong("Attack cooldown")} by ${values} by ${this.level} levels`;
  }
  registerAugmenter(stat) {
    const talent = this;
    stat.addAugmenter("attackCooldown", (v) => Math.floor((v * (100 - talent.max())) / 100));
  }
  augmentAttributes() {
    return ["attack_cooldown", "dps", "dps_sum"];
  }
}

class TalentList extends Talent {
  augment(stat) {
    super.augment(stat);

    const target = stat.abilities.find((a) => a instanceof this.ability.constructor);
    if (target) {
      target.list.push(...this.ability.list);
      const capitalized = this.ability.constructor.List.map(
        (t) => t.charAt(0).toUpperCase() + t.slice(1)
      );
      target.list.sort((a, b) => capitalized.indexOf(a) - capitalized.indexOf(b));
    } else {
      // Duplicate the list so a later Specialization/Immunity talent can't
      // mutate the list still referenced by this talent's own `ability`.
      stat.abilities.push(new this.ability.constructor([...this.ability.list]));
    }
  }

  augmentAttributes() {
    const prefix = this.ability.qualifiedValueName;
    return this.ability.list.map((item) => `${prefix}.${item}`);
  }
}

export class Specialization extends TalentList {
  constructor(key, data, ability) {
    super(key, data, ability);
    if (!this.ability) {
      const type = key.replace(/^against_/, "");
      this.ability = new Ability.Specialization([capitalize(type)]);
    }
  }
}

export class TalentImmunity extends TalentList {
  constructor(key, data) {
    super(key, data, undefined);
    const type = key.replace(/^immune_/, "");
    this.ability = new Ability.Immunity([capitalize(type)]);
  }
}

class Standalone extends Talent {
  augment(stat) {
    super.augment(stat);
    stat.abilities.push(this.ability);
  }
  augmentAttributes() {
    return [this.qualifiedName];
  }
}

export class Strong extends Standalone {
  constructor(key, data) {
    super(key, data, new Ability.Strong());
  }
}

